#![allow(unused, non_snake_case, dead_code, clippy::all)]
use ccxt::Value;
use ccxt::get_value;
use ccxt::runtime::*;
use crate::tests_support::{ArrayCache, ArrayCacheByTimestamp, ArrayCacheBySymbolById, ArrayCacheBySymbolBySide};
use ccxt::exchange_generated::ExchangeBase;

pub fn testHandleHttpStatusCode() {
    let mut exchange = crate::tests_support::make_exchange(Value::Map({
        let mut m = indexmap::IndexMap::new();
            m.insert("id".to_string(), Value::Str("sampleexchange".into()));
        m
    }));
    // every status of the default httpExceptions table must throw — one status
    // per distinct error class of the table.
    //
    // The blocks below are deliberately written out one status at a time with
    // integer literals instead of looping over a list of codes:
    //   - the C# and Java bases declare `handleHttpStatusCode (int code, ...)`,
    //     so an element read out of an untyped list does not compile there;
    //   - only *that* a status throws is asserted, never which class, because
    //     `error instanceof <Class>` inside a transpiled catch does not survive
    //     the Go port (the recover handler compares the panic payload's type
    //     against the constructor). The status → class mapping is pinned by
    //     ts/src/test/base/errors/* instead — do not weaken this list by adding
    //     statuses that are absent from httpExceptions.
    let mut caught: Value = Value::Bool(false);
    let _try_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        exchange.handle_http_status_code(Value::Int(429), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
     #[allow(unreachable_code)] { Value::Null }}));
if let Err(_try_err) = _try_result { let error: Value = panic_to_value(_try_err);
        caught = Value::Bool(true);
    }
    assert!(ccxt::runtime::is_true(&(caught.clone())));
    caught = Value::Bool(false);
    let _try_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        exchange.handle_http_status_code(Value::Int(418), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
     #[allow(unreachable_code)] { Value::Null }}));
if let Err(_try_err) = _try_result { let error: Value = panic_to_value(_try_err);
        caught = Value::Bool(true);
    }
    assert!(ccxt::runtime::is_true(&(caught.clone())));
    caught = Value::Bool(false);
    let _try_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        exchange.handle_http_status_code(Value::Int(401), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
     #[allow(unreachable_code)] { Value::Null }}));
if let Err(_try_err) = _try_result { let error: Value = panic_to_value(_try_err);
        caught = Value::Bool(true);
    }
    assert!(ccxt::runtime::is_true(&(caught.clone())));
    caught = Value::Bool(false);
    let _try_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        exchange.handle_http_status_code(Value::Int(408), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
     #[allow(unreachable_code)] { Value::Null }}));
if let Err(_try_err) = _try_result { let error: Value = panic_to_value(_try_err);
        caught = Value::Bool(true);
    }
    assert!(ccxt::runtime::is_true(&(caught.clone())));
    caught = Value::Bool(false);
    let _try_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        exchange.handle_http_status_code(Value::Int(500), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
     #[allow(unreachable_code)] { Value::Null }}));
if let Err(_try_err) = _try_result { let error: Value = panic_to_value(_try_err);
        caught = Value::Bool(true);
    }
    assert!(ccxt::runtime::is_true(&(caught.clone())));
    caught = Value::Bool(false);
    let _try_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        exchange.handle_http_status_code(Value::Int(422), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
     #[allow(unreachable_code)] { Value::Null }}));
if let Err(_try_err) = _try_result { let error: Value = panic_to_value(_try_err);
        caught = Value::Bool(true);
    }
    assert!(ccxt::runtime::is_true(&(caught.clone())));
    // statuses missing from the table must not throw — derived handleErrors
    // implementations rely on exactly that swallow when they guard with
    // a httpExceptions lookup before deferring to the status handler
    exchange.handle_http_status_code(Value::Int(402), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    exchange.handle_http_status_code(Value::Int(406), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    exchange.handle_http_status_code(Value::Int(412), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    exchange.handle_http_status_code(Value::Int(413), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    exchange.handle_http_status_code(Value::Int(505), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    exchange.handle_http_status_code(Value::Int(524), Value::Str("reason".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    // success statuses never throw
    exchange.handle_http_status_code(Value::Int(200), Value::Str("OK".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    exchange.handle_http_status_code(Value::Int(201), Value::Str("Created".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("body".into()));
    // dispatch composition: the base handleErrors stub returns undefined, so an
    // error envelope on an uncovered status passes both steps without a throw —
    // a derived handleErrors that wants to surface it must throw on its own
    let mut skip: Value = exchange.handle_errors(Value::Int(406), Value::Str("Not Acceptable".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Map({
        let mut m = indexmap::IndexMap::new();
        m
    }), Value::Str("{\"success\":false}".into()), Value::Map({
        let mut m = indexmap::IndexMap::new();
            m.insert("success".to_string(), Value::Bool(false));
        m
    }), Value::Map({
        let mut m = indexmap::IndexMap::new();
        m
    }), Value::Str("".into()));
    assert!(ccxt::runtime::is_true(&((skip == Value::Null))));
    exchange.handle_http_status_code(Value::Int(406), Value::Str("Not Acceptable".into()), Value::Str("url".into()), Value::Str("GET".into()), Value::Str("{\"success\":false}".into()));
}